interface Logger {
  log(msg: string): void;
}
class ConsoleLogger implements Logger {
  log(msg: string) { console.log(msg); }
}
class NullLogger implements Logger {
  log(msg: string) { /* no-op */ }
}

interface DiscountProvider {
  getDiscount(amount: number): number;
}
class RealDiscount implements DiscountProvider {
  getDiscount(amount:number) { return amount > 100 ? 10 : 0; }
}
class NoDiscount implements DiscountProvider {
  getDiscount(amount:number) { return 0; }
}

// Version A
interface MessageSender { send(msg: string): void }
class NoopSender implements MessageSender { send(msg:string) { /* no-op */ } }
class Notifier {
  constructor(private sender: MessageSender) {}
  notify(m:string){ this.sender.send(m) }
}

// Version B
class NotifierB {
  constructor(private sender?: MessageSender) {}
  notify(m:string){ if (this.sender) { this.sender.send(m) } }
}
